# ---- Expanded track condition / surface / weather system ----
DIRT_CONDITIONS = ["Fast/Firm", "Good", "Good to Soft", "Soft", "Heavy", "Muddy/Sloppy", "Sealed"]
TURF_CONDITIONS = ["Fast/Firm", "Good", "Good to Soft", "Soft", "Heavy", "Yielding"]
SURFACE_TYPES = ["Dirt", "Turf", "Synthetic"]
WEATHER_TYPES = ["Clear", "Clear", "Rainy", "Windy", "Hot & Humid"]  # Clear weighted more common

def roll_track_conditions():
    """Randomly (but sensibly) pick a surface, weather, and matching track condition."""
    weather = random.choice(WEATHER_TYPES)
    surface = random.choice(SURFACE_TYPES)
    pool = TURF_CONDITIONS if surface == "Turf" else DIRT_CONDITIONS
    if surface == "Synthetic":
        condition = random.choice(["Good", "Good to Soft", "Fast/Firm"])
    elif weather == "Rainy":
        wet_pool = [c for c in pool if c in ("Soft", "Heavy", "Muddy/Sloppy", "Sealed", "Yielding")]
        condition = random.choice(wet_pool) if wet_pool else random.choice(pool)
    else:
        dry_pool = [c for c in pool if c in ("Fast/Firm", "Good", "Good to Soft")]
        condition = random.choice(dry_pool) if dry_pool else random.choice(pool)
    return condition, surface, weather

def compute_condition_modifier(traits, condition, surface, weather):
    """How a horse's genetic traits interact with today's surface/condition/weather."""
    mod = 1.0
    wet_conditions = {"Heavy", "Muddy/Sloppy", "Soft", "Sealed", "Yielding"}
    dry_conditions = {"Fast/Firm"}
    stamina_favoring = {"Heavy", "Soft", "Yielding", "Good to Soft"}

    if "Mudder" in traits:
        if condition in wet_conditions:
            mod += 0.15
    else:
        if condition in {"Heavy", "Muddy/Sloppy"}:
            mod -= 0.05

    if "Stamina" in traits and condition in stamina_favoring:
        mod += 0.06

    if "Early Speed" in traits:
        if condition in dry_conditions or condition == "Sealed":
            mod += 0.05
        elif condition in wet_conditions:
            mod -= 0.04

    if "Closer" in traits:
        if condition in {"Good", "Good to Soft"}:
            mod += 0.04
        elif condition in dry_conditions:
            mod -= 0.03

    if surface == "Turf":
        if "Closer" in traits: mod += 0.03
        if "Early Speed" in traits: mod -= 0.02
    if surface == "Synthetic":
        mod = 1.0 + (mod - 1.0) * 0.5

    if weather == "Hot & Humid" and "Iron Horse" not in traits:
        mod -= 0.02
    if weather == "Windy":
        mod += random.uniform(-0.03, 0.03)

    return mod

