def is_triple_crown_eligible(h):
    """Only the rarest horses qualify: exactly 3 years old, at the absolute conformation
    ceiling (97, the max a horse can reach), never yet attempted the Crown."""
    return (h.age == 3 and h.conf_score >= 97 and not h.retired
            and getattr(h, 'triple_crown_status', None) is None)

def display_name(h):
    return f"👑 {h.name}" if getattr(h, 'triple_crown_status', None) == 'champion' else h.name

# ====================== HORSE CLASS ======================
class Horse:
    def __init__(self, name, age, sex, conf_score=75, color="Bay", value=None, birth_year=2026, sire="Unknown", dam="Unknown", traits=None, horse_id=None, newborn=False):
        self.id = horse_id or uuid.uuid4().hex[:10]
        self.name = name
        self.age = age
        self.sex = sex
        self.conf_score = conf_score
        self.color = color
        self.value = value or int(conf_score * 450 + random.randint(-5000, 15000))
        self.birth_year = birth_year
        self.starts = 0
        self.wins = 0
        self.seconds = 0
        self.thirds = 0
        self.earnings = 0
        self.trainer = "None (Pasture)"
        self.breeder = "You"
        self.owner = "You"
        self.retired = False

        # Genetics & Health Loop
        self.sire = sire
        self.dam = dam
        self.sire_id = None
        self.dam_id = None
        self.traits = traits if traits else random.sample(ALL_TRAITS, random.randint(1, 2))
        self.fitness = 100
        self.is_injured = False
        self.injury_time = 0
        self.live_races_this_season = 0

        # Breeding / pregnancy lifecycle
        self.is_pregnant = False
        self.pregnancy_seasons_left = 0
        self.postpartum_seasons_left = 0
        self.pending_foal = None

        # A freshly foaled horse needs one season before it can start training
        self.newborn = newborn

        # Triple Crown campaign tracking
        self.triple_crown_status = None  # None, "active", "failed", "champion"
        self.triple_crown_leg = 0
        self.triple_crown_wins = 0

    def to_dict(self):
        d = self.__dict__.copy()
        d['traits'] = ", ".join(self.traits)
        return d

    @classmethod
    def from_dict(cls, d):
        """Rebuild a Horse from a plain dict (used by Save/Load)."""
        traits = d.get("traits", [])
        if isinstance(traits, str):
            traits = [t.strip() for t in traits.split(",") if t.strip()]
        h = cls(
            name=d.get("name", "Unnamed"), age=d.get("age", 1), sex=d.get("sex", "Colt"),
            conf_score=d.get("conf_score", 75), color=d.get("color", "Bay"),
            value=d.get("value"), birth_year=d.get("birth_year", 2026),
            sire=d.get("sire", "Unknown"), dam=d.get("dam", "Unknown"),
            traits=traits or None, horse_id=d.get("id")
        )
        for field in ["starts", "wins", "seconds", "thirds", "earnings", "trainer", "breeder",
                      "owner", "retired", "fitness", "is_injured", "injury_time", "live_races_this_season",
                      "sire_id", "dam_id", "is_pregnant", "pregnancy_seasons_left",
                      "postpartum_seasons_left", "pending_foal", "newborn",
                      "triple_crown_status", "triple_crown_leg", "triple_crown_wins"]:
            if field in d:
                setattr(h, field, d[field])
        return h

    def age_up(self):
        self.age += 1
        if self.age < 5:
            self.conf_score = min(97, self.conf_score + random.randint(0, 4))
        else:
            self.conf_score = max(60, self.conf_score - random.randint(0, 4))
        self.value = int(self.conf_score * 420 + random.randint(-15000, 30000))

    def recover_health(self, vet_clinic_active, advanced_vet_active=False):
        """Every season, a healthy horse's fitness is fully restored to 100%.
        An injured horse instead works through its recovery timeline."""
        if self.is_injured:
            reduction = 3 if advanced_vet_active else (2 if vet_clinic_active else 1)
            self.injury_time -= reduction
            if self.injury_time <= 0:
                self.is_injured = False
                self.injury_time = 0
                self.fitness = 100
        else:
            self.fitness = 100

    def train_season(self, trainer_skill, premium_track_active=False, elite_center_active=False):
        """Conformation grows each season based on trainer quality and facilities."""
        growth = (trainer_skill - 0.80) * 4 + random.uniform(0.3, 1.2)
        if premium_track_active and self.age <= 4:
            growth += 1.0
        if elite_center_active:
            growth += 0.8
        cap = 97 if self.age < 6 else (92 if self.age < 9 else 85)
        self.conf_score = int(round(min(cap, self.conf_score + growth)))

    def roll_injury_chance(self):
        """Fitness-tiered injury risk. Very tired horses (<25% fitness) are much
        more likely to come out of a race hurt."""
        if self.fitness < 25:
            chance = 0.18
        elif self.fitness < 60:
            chance = 0.08
        else:
            chance = 0.02
        if "Fragile" in self.traits:
            chance *= 2
        if st.session_state.facilities.get("Advanced Vet Clinic", False):
            chance *= 0.25
        elif st.session_state.facilities.get("Vet Clinic", False):
            chance *= 0.5
        return chance

    def simulate_season_races(self, trainer_skill, jockey_skill, jockey_cut_rate, target_class):
        if self.retired or self.age < 2 or self.is_injured or self.is_pregnant or self.postpartum_seasons_left > 0:
            return 0, 0, 0, []
        if target_class == "Maiden" and self.wins > 0:
            return 0, 0, 0, [f"🚫 {self.name} is no longer Maiden-eligible and was withdrawn from that race."]

        races_this_season = 3  # exactly 3 of the 4 possible race slots this season
        owner_season_earnings = 0
        trainer_season_cut = 0
        jockey_season_cut = 0
        events_log = []
        publicity = st.session_state.facilities.get("Publicity Office", False)

        for _ in range(races_this_season):
            if target_class == "Maiden" and self.wins > 0:
                break

            if self.fitness < 40:
                events_log.append(f"🐎 {self.name} was too fatigued to run and was scratched.")
                continue

            self.starts += 1
            self.fitness = max(0, self.fitness - random.randint(15, 25))
            if "Iron Horse" in self.traits: self.fitness = min(100, self.fitness + 5)

            injury_chance = self.roll_injury_chance()
            if random.random() < injury_chance:
                self.is_injured = True
                self.injury_time = random.randint(1, 3)
                vet_bill = random.randint(2000, 8000)
                st.session_state.bankroll -= vet_bill
                events_log.append(f"⚠️ {self.name} sustained an injury on the track! Vet bill: ${vet_bill:,}.")
                log_news("⚠️", f"{self.name} was injured racing in {target_class} company and will need {self.injury_time} season(s) to heal.")
                break

            info = SEASON_CLASS_INFO[target_class]
            purse = random.randint(*info["purse"])
            field_strength = random.uniform(*info["field"])

            trait_mod = 1.0
            if "Stamina" in self.traits and target_class in ("Stakes", "Grade 3", "Grade 2", "Grade 1"): trait_mod += 0.05
            if "Closer" in self.traits: trait_mod += random.uniform(-0.05, 0.10)
            if "Heart" in self.traits: trait_mod += 0.03

            performance = self.conf_score * trainer_skill * jockey_skill * random.uniform(0.75, 1.25) * trait_mod
            race_earnings = 0

            if performance > field_strength + 10:
                self.wins += 1
                race_earnings = purse * 0.60
                rep_gain = 1.5 if publicity else 1
                st.session_state.reputation = round(st.session_state.reputation + rep_gain, 1)
                if target_class in ("Stakes", "Grade 3", "Grade 2", "Grade 1"):
                    log_news("🏆", f"{self.name} won a {target_class} race, earning ${race_earnings * 0.9:,.0f} for the barn!")
            elif performance > field_strength + 5:
                self.seconds += 1
                race_earnings = purse * 0.20
            elif performance > field_strength:
                self.thirds += 1
                race_earnings = purse * 0.10

            t_cut = race_earnings * 0.10
            j_cut = race_earnings * jockey_cut_rate
            owner_share = race_earnings - t_cut - j_cut

            owner_season_earnings += owner_share
            trainer_season_cut += t_cut
            jockey_season_cut += j_cut
            self.earnings += owner_share

            if owner_share > 0:
                events_log.append(f"🏆 {self.name} won ${owner_share:,.2f} in {target_class} company.")
            else:
                events_log.append(f"🐎 {self.name} ran out of the money in {target_class} company.")

        return owner_season_earnings, trainer_season_cut, jockey_season_cut, events_log

# ====================== HELPER FUNCTIONS ======================
def register_horse(h):
    if 'horse_registry' not in st.session_state:
        st.session_state.horse_registry = {}
    st.session_state.horse_registry[h.id] = {
        "name": h.name, "sire_id": getattr(h, 'sire_id', None), "dam_id": getattr(h, 'dam_id', None)
    }

def get_ancestor_ids(horse_id, max_gen=2):
    registry = st.session_state.get('horse_registry', {})
    result = set()
    frontier = {horse_id}
    for _ in range(max_gen):
        next_frontier = set()
        for hid in frontier:
            rec = registry.get(hid)
            if not rec:
                continue
            for parent_id in (rec.get('sire_id'), rec.get('dam_id')):
                if parent_id:
                    next_frontier.add(parent_id)
        result |= next_frontier
        frontier = next_frontier
        if not frontier:
            break
    return result

def check_inbreeding(stallion_id, mare_id):
    if not stallion_id or not mare_id:
        return False
    s_line = {stallion_id} | get_ancestor_ids(stallion_id, 2)
    m_line = {mare_id} | get_ancestor_ids(mare_id, 2)
    return len(s_line & m_line) > 0

def log_news(icon, text):
    if 'news_log' not in st.session_state:
        st.session_state.news_log = []
    st.session_state.news_log.insert(0, {
        "year": st.session_state.get("current_year", 2026),
        "season": st.session_state.get("season", "Spring"),
        "text": f"{icon} {text}"
    })
    st.session_state.news_log = st.session_state.news_log[:300]

def weighted_order(entries):
    """Draw a full finishing order via weighted sampling without replacement
    (Plackett-Luce style), so the betting favorite is favored but NOT guaranteed
    to win -- this is what makes upsets possible."""
    pool = list(entries)
    order = []
    while pool:
        weights = [max(e["weight"], 0.0001) for e in pool]
        total = sum(weights)
        r = random.uniform(0, total)
        upto = 0
        for i, w in enumerate(weights):
            upto += w
            if upto >= r:
                order.append(pool.pop(i))
                break
        else:
            order.append(pool.pop())
    return order

def build_race_html(color_order, names_by_color):
    """Builds the animated oval race: a single starting beep, dots that can genuinely
    change position mid-race, and a track-announcer feed whose commentary is generated
    from the ACTUAL live standings at each checkpoint (not a spoiler of the final order).
    color_order: list of 8 colors in the true final finishing order (winner first).
    names_by_color: dict color -> displayed horse name.
    """
    uid = uuid.uuid4().hex[:8]
    js_finishing_order = json.dumps(color_order)
    names_json = json.dumps(names_by_color)
    lane_map_json = json.dumps({c: i for i, c in enumerate(COLOR_POST_ORDER)})
    hex_json = json.dumps(COLOR_HEX)

    return f"""
    <div style="display: flex; justify-content: center; background: #222; padding: 20px; border-radius: 10px; flex-direction: column; align-items: center;">
    <canvas id="trackCanvas_{uid}" width="800" height="420" style="background:#45a247; border: 4px solid #111; border-radius: 20px; box-shadow: 0 4px 8px rgba(0,0,0,0.5);"></canvas>
    <div id="announcerFeed_{uid}" style="width:760px; max-width:100%; margin-top:14px; background:#111; color:#f0f0f0; font-family: Georgia, serif; font-size:15px; padding:12px 16px; border-radius:10px; height:150px; overflow-y:auto; box-shadow: inset 0 0 8px rgba(0,0,0,0.6);">
        <div style="color:#ffcc66; font-weight:bold; margin-bottom:6px;">📻 TURFHILL DOWNS TRACK ANNOUNCER</div>
    </div>
    </div>
    <script>
    (function() {{
        const canvas = document.getElementById('trackCanvas_{uid}');
        const ctx = canvas.getContext('2d');
        const feed = document.getElementById('announcerFeed_{uid}');
        const finishingOrder = {js_finishing_order};
        const namesByColor = {names_json};
        const colorToLaneMap = {lane_map_json};
        const colorHexes = {hex_json};

        function addFeedLine(text) {{
            const line = document.createElement('div');
            line.textContent = text;
            line.style.padding = '3px 0';
            line.style.borderTop = '1px solid #333';
            feed.appendChild(line);
            feed.scrollTop = feed.scrollHeight;
        }}

        function playStartBeep() {{
            try {{
                const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
                const now = audioCtx.currentTime;
                const osc = audioCtx.createOscillator();
                const gain = audioCtx.createGain();
                osc.type = 'square';
                osc.frequency.value = 1000;
                gain.gain.setValueAtTime(0.0001, now);
                gain.gain.exponentialRampToValueAtTime(0.4, now + 0.02);
                gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.45);
                osc.connect(gain);
                gain.connect(audioCtx.destination);
                osc.start(now);
                osc.stop(now + 0.46);
            }} catch (e) {{ /* autoplay may be blocked; race continues silently */ }}
        }}

        const gateDelayMs = 0;
        const raceDurationMs = 27000;
        const maxStaggerMs = 3000;
        const totalWindow = raceDurationMs + maxStaggerMs;

        playStartBeep();
        addFeedLine("🔔 And they're off and racing at Turfhill Downs!");

        let runners = [];
        for (let lane = 0; lane < 8; lane++) {{
            let color = Object.keys(colorToLaneMap).find(k => colorToLaneMap[k] === lane);
            let finishingRank = finishingOrder.indexOf(color);
            runners.push({{
                lane: lane, color: color, finishingRank: finishingRank,
                finishTime: raceDurationMs + finishingRank * (maxStaggerMs / 7),
                // Each horse gets its own pace "shape": exponent < 1 breaks fast and fades
                // (early speed), exponent > 1 saves its best for the end (a closer). Because
                // progress = (elapsed/finishTime) ^ exponent is strictly increasing on [0,1]
                // for any positive exponent, motion is ALWAYS forward -- never backward --
                // while still letting horses trade the lead realistically along the way.
                // Narrow range keeps the whole field bunched together and genuinely jockeying
                // for position, instead of spreading out into different apparent speeds.
                paceExponent: 0.85 + Math.random() * 0.3
            }});
        }}

        function computeStandings(elapsed) {{
            return runners.map(h => {{
                const ratio = Math.min(Math.max(elapsed / h.finishTime, 0), 1);
                const progress = Math.pow(ratio, h.paceExponent);
                return {{ color: h.color, lane: h.lane, name: namesByColor[h.color], progress: progress, rank: h.finishingRank }};
            }}).sort((a, b) => (b.progress - a.progress) || (a.rank - b.rank));
        }}

        const cy = 210, leftX = 250, rightX = 550, innerR = 110, outerR = 170;

        function drawTrack() {{
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.beginPath();
            ctx.arc(leftX, cy, outerR, Math.PI/2, Math.PI*1.5);
            ctx.lineTo(rightX, cy - outerR);
            ctx.arc(rightX, cy, outerR, Math.PI*1.5, Math.PI/2);
            ctx.closePath();
            ctx.fillStyle = "#A0522D";
            ctx.fill();
            ctx.strokeStyle = "#ffffff";
            ctx.lineWidth = 3;
            ctx.stroke();

            ctx.fillStyle = "#A0522D";
            ctx.fillRect(70, cy + innerR - 2, leftX - 70, outerR - innerR + 4);

            const intersectX = leftX - Math.sqrt((outerR*outerR) - (innerR*innerR));
            ctx.beginPath();
            ctx.moveTo(leftX, cy + outerR);
            ctx.lineTo(70, cy + outerR);
            ctx.lineTo(70, cy + innerR);
            ctx.lineTo(intersectX, cy + innerR);
            ctx.stroke();

            ctx.beginPath();
            ctx.arc(leftX, cy, innerR, Math.PI/2, Math.PI*1.5);
            ctx.lineTo(rightX, cy - innerR);
            ctx.arc(rightX, cy, innerR, Math.PI*1.5, Math.PI/2);
            ctx.closePath();
            ctx.fillStyle = "#45a247";
            ctx.fill();
            ctx.stroke();

            const turfOuterR = innerR - 15;
            const turfInnerR = turfOuterR - 25;
            ctx.beginPath();
            ctx.arc(leftX, cy, turfOuterR, Math.PI/2, Math.PI*1.5);
            ctx.lineTo(rightX, cy - turfOuterR);
            ctx.arc(rightX, cy, turfOuterR, Math.PI*1.5, Math.PI/2);
            ctx.closePath();
            ctx.fillStyle = "#337a33";
            ctx.fill();

            ctx.beginPath();
            ctx.arc(leftX, cy, turfInnerR, Math.PI/2, Math.PI*1.5);
            ctx.lineTo(rightX, cy - turfInnerR);
            ctx.arc(rightX, cy, turfInnerR, Math.PI*1.5, Math.PI/2);
            ctx.closePath();
            ctx.fillStyle = "#45a247";
            ctx.fill();
            ctx.strokeStyle = "#e0e0e0";
            ctx.lineWidth = 1.5;
            ctx.stroke();

            const startFinishX = 480;
            ctx.beginPath();
            ctx.moveTo(startFinishX, cy + innerR);
            ctx.lineTo(startFinishX, cy + outerR);
            ctx.strokeStyle = "#ffffff";
            ctx.lineWidth = 4;
            ctx.stroke();
        }}

        function getPosition(lane, progress) {{
            const laneR = innerR + 6 + (lane * 6.5);
            const straightLen = rightX - leftX;
            const curveLen = Math.PI * laneR;
            const totalLen = (straightLen * 2) + (curveLen * 2);
            let dist = progress * totalLen;
            const startXPos = 480;
            const seg1Len = rightX - startXPos;
            if (dist <= seg1Len) {{ return {{ x: startXPos + dist, y: cy + laneR }}; }}
            dist -= seg1Len;
            if (dist <= curveLen) {{
                const angle = (Math.PI / 2) - (dist / curveLen) * Math.PI;
                return {{ x: rightX + laneR * Math.cos(angle), y: cy + laneR * Math.sin(angle) }};
            }}
            dist -= curveLen;
            if (dist <= straightLen) {{ return {{ x: rightX - dist, y: cy - laneR }}; }}
            dist -= straightLen;
            if (dist <= curveLen) {{
                const angle = (-Math.PI / 2) - (dist / curveLen) * Math.PI;
                return {{ x: leftX + laneR * Math.cos(angle), y: cy + laneR * Math.sin(angle) }};
            }}
            dist -= curveLen;
            return {{ x: leftX + dist, y: cy + laneR }};
        }}

        const checkpointFracs = [0.28, 0.52, 0.75, 0.92, 1.0];
        const checkpointLabels = [
            (s) => `Down the backstretch, ${{s[0].name}} shows in front, with ${{s[1].name}} and ${{s[2].name}} in close pursuit.`,
            (s) => `Turning for home, ${{s[0].name}} is up on top as ${{s[1].name}} looks for room to make a move.`,
            (s) => `Into the stretch! ${{s[0].name}} is digging in, ${{s[1].name}} is not going away easily.`,
            (s) => `Deep in the stretch now, ${{s[0].name}} looks for the wire...`,
            (s) => `📣 AND IT'S ${{s[0].name.toUpperCase()}} BY THE WIRE! ${{s[1].name}} second, ${{s[2].name}} third.`
        ];
        checkpointFracs.forEach((frac, idx) => {{
            const atTime = frac * totalWindow;
            setTimeout(() => {{
                const standings = computeStandings(atTime);
                addFeedLine(checkpointLabels[idx](standings));
            }}, gateDelayMs + atTime);
        }});

        let startTime = null;
        function loop(timestamp) {{
            if (!startTime) startTime = timestamp;
            const elapsed = timestamp - startTime;
            drawTrack();
            const standings = computeStandings(elapsed);
            let allFinished = true;
            standings.forEach(s => {{
                if (s.progress < 1.0) allFinished = false;
                const pos = getPosition(s.lane, s.progress);
                ctx.fillStyle = colorHexes[s.color];
                ctx.beginPath();
                ctx.arc(pos.x, pos.y, 5, 0, 2 * Math.PI);
                ctx.fill();
                ctx.strokeStyle = "#000";
                ctx.lineWidth = 1.5;
                ctx.stroke();
            }});
            if (!allFinished) {{ requestAnimationFrame(loop); }}
        }}

        drawTrack();
        setTimeout(() => requestAnimationFrame(loop), gateDelayMs);
    }})();
    </script>
    """

RACE_ANIMATION_WAIT_SECONDS = 31.0  # winner at 27s, last place at 30s, results posted at 31s

def generate_market():
    facilities = st.session_state.get('facilities', {})
    if facilities.get("Bloodstock Manager III", False):
        bm_level = 3
    elif facilities.get("Bloodstock Manager II", False):
        bm_level = 2
    elif facilities.get("Bloodstock Manager I", False):
        bm_level = 1
    else:
        bm_level = 0
    market_tiers = {
        0: {"count": (0, 5), "conf": (62, 85)},
        1: {"count": (2, 7), "conf": (68, 92)},
        2: {"count": (3, 8), "conf": (70, 94)},
        3: {"count": (4, 9), "conf": (72, 96)},
    }
    tier = market_tiers[bm_level]
    num_horses = random.randint(*tier["count"])
    conf_low, conf_high = tier["conf"]
    horses = [Horse(
        generate_horse_name(), 1, random.choice(["Colt", "Filly"]),
        random.randint(conf_low, conf_high), random.choice(["Bay", "Chestnut", "Gray", "Black", "Dark Bay"]),
        sire="Unknown (Auction)", dam="Unknown (Auction)"
    ) for _ in range(num_horses)]
    for h in horses:
        register_horse(h)
    return horses

def advance_season_logic():
    seasons = ["Spring", "Summer", "Fall", "Winter"]
    idx = seasons.index(st.session_state.season)
    st.session_state.season = seasons[(idx + 1) % 4]

    vet_active = st.session_state.facilities.get("Vet Clinic", False)
    adv_vet_active = st.session_state.facilities.get("Advanced Vet Clinic", False)
    premium_track = st.session_state.facilities.get("Premium Track", False)
    elite_center = st.session_state.facilities.get("Elite Training Center", False)

    newly_born = []
    for horse in st.session_state.stable:
        if horse.is_pregnant:
            horse.pregnancy_seasons_left -= 1
            if horse.pregnancy_seasons_left <= 0:
                info = horse.pending_foal or {}
                foal = Horse(
                    info.get("name", generate_horse_name()), 0, info.get("sex", random.choice(["Colt", "Filly"])),
                    info.get("conf", 70), info.get("color", "Bay"),
                    birth_year=st.session_state.current_year, sire=info.get("sire_name", "Unknown"), dam=horse.name,
                    traits=info.get("traits"), newborn=True
                )
                foal.breeder = st.session_state.stable_name
                foal.sire_id = info.get("sire_id")
                foal.dam_id = horse.id
                newly_born.append(foal)
                register_horse(foal)
                horse.is_pregnant = False
                horse.pending_foal = None
                horse.postpartum_seasons_left = 1
                log_news("🐴", f"{horse.name} foaled a {foal.sex.lower()}, {foal.name}, sired by {info.get('sire_name', 'Unknown')}.")
            continue
        if horse.postpartum_seasons_left > 0:
            horse.postpartum_seasons_left -= 1
            horse.live_races_this_season = 0
            continue

        horse.recover_health(vet_active, adv_vet_active)
        horse.live_races_this_season = 0
        is_newborn = getattr(horse, 'newborn', False)
        if not horse.retired and horse.trainer != "None (Pasture)" and not horse.is_injured and not is_newborn:
            t_skill = trainers_data[horse.trainer]["skill"]
            horse.train_season(t_skill, premium_track, elite_center)
        horse.newborn = False

    st.session_state.stable.extend(newly_born)

    if st.session_state.season == "Spring":
        st.session_state.current_year += 1
        for horse in st.session_state.stable:
            horse.age_up()
            if horse.age >= 11 and not horse.retired:
                horse.retired = True
                horse.trainer = "None (Pasture)"
                log_news("🎓", f"{horse.name} has been retired from racing at age {horse.age}.")
        st.session_state.market = generate_market()
        log_news("📰", f"The {st.session_state.current_year} Yearling Sale catalog has been released.")

def get_horse_by_id(horse_id):
    return next((h for h in st.session_state.stable if h.id == horse_id), None)

def safe_options(data_dict, current_selection=None):
    options = [
        key for key, info in data_dict.items()
        if info["req_bankroll"] == 0
        or st.session_state.bankroll >= info["req_bankroll"]
        or key == current_selection
    ]
    if not options:
        options = [list(data_dict.keys())[0]]
    return options

def render_locked_note(data_dict, label):
    """Explains WHY certain trainers/jockeys aren't in the dropdown -- it's always
    a bankroll threshold, never a bug -- and shows exactly what's needed to unlock them."""
    locked = [(k, v) for k, v in data_dict.items() if v["req_bankroll"] > 0 and st.session_state.bankroll < v["req_bankroll"]]
    if locked:
        with st.expander(f"🔒 Locked {label} (unlock with a bigger bankroll)"):
            for k, v in sorted(locked, key=lambda kv: kv[1]["req_bankroll"]):
                short_by = v["req_bankroll"] - st.session_state.bankroll
                st.caption(f"**{k}** — needs ${v['req_bankroll']:,} bankroll (${short_by:,.0f} more than you have now)")

def generate_opponent_profile(conf):
    """Fabricate a plausible full profile (age/sex/traits/record) for an AI opponent,
    used both for display and for post-race claiming."""
    age = random.randint(2, 8)
    sex = random.choice(["Colt", "Filly"])
    traits = random.sample(ALL_TRAITS, random.randint(1, 2))
    starts = random.randint(2, 16)
    wins = min(starts, max(0, int(starts * random.uniform(0.05, 0.30) * (conf / 75))))
    remaining = starts - wins
    seconds = random.randint(0, remaining)
    thirds = random.randint(0, max(0, remaining - seconds))
    return {"age": age, "sex": sex, "traits": traits, "starts": starts, "wins": wins, "seconds": seconds, "thirds": thirds}

