SILK_PATTERNS = ["Solid", "Stripes", "Hoops", "Polka Dots", "Checks", "Stars", "Moon", "Monogram"]

def build_silks_svg(pattern, primary, secondary, letters="AB", width=140):
    """Renders a jockey silk (cap + sleeves + body) as an inline SVG string.
    Real jockey-silk pattern vocabulary: Solid, Stripes, Hoops, Spots, Checks, Stars, Moon/Crescent, Monogram."""
    height = int(width * 1.27)
    defs = ""
    body_fill = primary
    accent_fill = secondary
    overlay = ""

    if pattern == "Stripes":
        defs = (f'<defs><pattern id="silkPat" width="17" height="{height}" patternUnits="userSpaceOnUse">'
                f'<rect width="17" height="{height}" fill="{primary}"/><rect width="8.5" height="{height}" fill="{secondary}"/></pattern></defs>')
        body_fill = "url(#silkPat)"
    elif pattern == "Hoops":
        defs = (f'<defs><pattern id="silkPat" width="{width}" height="17" patternUnits="userSpaceOnUse">'
                f'<rect width="{width}" height="17" fill="{primary}"/><rect width="{width}" height="8.5" fill="{secondary}"/></pattern></defs>')
        body_fill = "url(#silkPat)"
    elif pattern == "Polka Dots":
        defs = (f'<defs><pattern id="silkPat" width="22" height="22" patternUnits="userSpaceOnUse">'
                f'<rect width="22" height="22" fill="{primary}"/><circle cx="11" cy="11" r="5" fill="{secondary}"/></pattern></defs>')
        body_fill = "url(#silkPat)"
    elif pattern == "Checks":
        defs = (f'<defs><pattern id="silkPat" width="20" height="20" patternUnits="userSpaceOnUse">'
                f'<rect width="20" height="20" fill="{primary}"/><rect width="10" height="10" fill="{secondary}"/>'
                f'<rect x="10" y="10" width="10" height="10" fill="{secondary}"/></pattern></defs>')
        body_fill = "url(#silkPat)"
    elif pattern == "Stars":
        overlay = "".join(
            f'<text x="{x}" y="{y}" font-size="19" fill="{secondary}" text-anchor="middle">\u2605</text>'
            for x, y in [(52, 105), (98, 105), (75, 128), (58, 153), (92, 153)]
        )
    elif pattern == "Moon":
        overlay = ('<circle cx="75" cy="118" r="24" fill="' + secondary + '"/>'
                   '<circle cx="85" cy="111" r="20" fill="' + primary + '"/>')
    elif pattern == "Monogram":
        safe_letters = (letters or "AB").strip()[:2].upper() or "AB"
        overlay = (f'<text x="75" y="135" font-size="36" font-weight="bold" fill="{secondary}" '
                   f'text-anchor="middle" font-family="Georgia, serif">{safe_letters}</text>')
    # "Solid": body_fill stays as primary, no overlay -- plain contrast body/trim

    return f'''<svg width="{width}" height="{height}" viewBox="0 0 150 190" xmlns="http://www.w3.org/2000/svg" style="display:block;">
{defs}
<circle cx="75" cy="26" r="24" fill="{accent_fill}" stroke="#1a1a1a" stroke-width="2.5"/>
<path d="M45,55 L15,85 L32,102 L52,75 Z" fill="{accent_fill}" stroke="#1a1a1a" stroke-width="2.5"/>
<path d="M105,55 L135,85 L118,102 L98,75 Z" fill="{accent_fill}" stroke="#1a1a1a" stroke-width="2.5"/>
<path d="M45,55 L105,55 L118,185 L32,185 Z" fill="{body_fill}" stroke="#1a1a1a" stroke-width="2.5"/>
{overlay}
</svg>'''

def render_current_silks(width=110):
    """Renders whatever silks the stable currently has -- the fixed generic look pre-purchase,
    or the player's customized pattern/colors/monogram once unlocked."""
    if st.session_state.get('silks_unlocked'):
        pattern = st.session_state.get('silk_pattern', 'Solid')
        primary = st.session_state.get('silk_blouse_color', '#9E9E9E')
        secondary = st.session_state.get('silk_cap_color', '#FFFFFF')
        letters = st.session_state.get('silk_monogram_letters', 'AB')
    else:
        pattern, primary, secondary, letters = "Solid", "#9E9E9E", "#FFFFFF", "AB"
    return build_silks_svg(pattern, primary, secondary, letters, width=width)

