                if st.button(f"{action_word} {fname} (${finfo['cost']:,})", key=f"build_{fname}"):
                    if st.session_state.bankroll >= finfo["cost"]:
                        st.session_state.bankroll -= finfo["cost"]
                        st.session_state.facilities[fname] = True
                        verb = "hired" if action_word == "Hire" else "built a new"
